func updateENR(node *enode.LocalNode, entry, next params.NetworkScheduleEntry) error {
	enrForkID := &pb.ENRForkID{
		CurrentForkDigest: entry.ForkDigest[:],  // 4 bytes from [4]byte
		NextForkVersion:   next.ForkVersion[:],  // 4 bytes from [4]byte
		NextForkEpoch:     next.Epoch,           // uint64 = 8 bytes
	}
	enc, err := enrForkID.MarshalSSZ()  // always produces exactly 16 bytes
	forkEntry := enr.WithEntry(eth2EnrKey, enc)
	node.Set(forkEntry)
}

func forkEntry(record *enr.Record) (*pb.ENRForkID, error) {
	sszEncodedForkEntry := make([]byte, 16)  // expects exactly 16 bytes
	entry := enr.WithEntry(eth2EnrKey, &sszEncodedForkEntry)
	err := record.Load(entry)  // overwrites with ENR content
	forkEntry := &pb.ENRForkID{}
	if err := forkEntry.UnmarshalSSZ(sszEncodedForkEntry); err != nil {  // strict size check
		return nil, err
	}
}

func compareForkENR(self, peer *enr.Record) error {
	// ... CurrentForkDigest, NextForkEpoch, NextForkVersion checks ...

	// VULNERABILITY: FuluEnabled() = FuluForkEpoch < math.MaxUint64
	// This is true whenever Fulu is SCHEDULED, NOT only when Fulu is ACTIVE
	if !params.FuluEnabled() {
		return nil
	}
	peerNFD, selfNFD := nfd(peer), nfd(self)
	if peerNFD != selfNFD {
		return errors.Wrapf(errNextDigestMismatch, ...)
		// ^ Disconnects peer pre-Fulu if peer lacks nfd entry
	}
}

